// OpenObject: The `OpenObject` object of the `kernel` module. It is open, so it keeps the members it doesn't name. An object whose keys another definition sets, such as an owner's extension or an object another standard defines, which the field that holds it names.
type OpenObject struct {
	// Extra holds the members the object doesn't name, which it keeps.
	Extra map[string]json.RawMessage `json:"-"`
}

// ValidateValue implements Value.
func (OpenObject) ValidateValue(v any, at string, errs *Errors) {
	objectValue(v, at, errs)
}

// UnmarshalJSON decodes the members OpenObject names into its fields, matching each name exactly, and keeps the others in Extra.
func (o *OpenObject) UnmarshalJSON(data []byte) error {
	type plain OpenObject
	known, extra, err := splitMembers(data)
	if err != nil {
		return err
	}
	var p plain
	if err := json.Unmarshal(known, &p); err != nil {
		return err
	}
	p.Extra = extra
	*o = OpenObject(p)
	return nil
}

// MarshalJSON encodes the members in Extra beside the ones OpenObject names.
func (o OpenObject) MarshalJSON() ([]byte, error) {
	type plain OpenObject
	return marshalOpen(plain(o), o.Extra)
}

