// Side: The `Side` vocabulary: `buyer`, `seller`.
type Side string

// SideBuyer is the term "buyer".
const SideBuyer Side = "buyer"

// SideSeller is the term "seller".
const SideSeller Side = "seller"

var termsSide = []any{"buyer", "seller"}

// ValidateValue implements Value.
func (Side) ValidateValue(v any, at string, errs *Errors) {
	checkEnum(v, at, errs, termsSide...)
}

// Measurer: The `Measurer` union: a value of any one of its branches.
type Measurer struct {
	// Side holds the value when it is a Side.
	Side *Side
	// RegistrableDomain holds the value when it is a RegistrableDomain.
	RegistrableDomain *RegistrableDomain
}

// ValidateValue implements Value: the value is valid in at least one branch.
func (Measurer) ValidateValue(v any, at string, errs *Errors) {
	validateAnyOf(v, at, errs, validateAs[Side], validateAs[RegistrableDomain])
}

// UnmarshalJSON sets the first branch the value is valid in.
func (u *Measurer) UnmarshalJSON(data []byte) error {
	v, err := ParseJSON(data)
	if err != nil {
		return err
	}
	*u = Measurer{}
	switch {
	case validates[Side](v):
		u.Side = new(Side)
		return json.Unmarshal(data, u.Side)
	case validates[RegistrableDomain](v):
		u.RegistrableDomain = new(RegistrableDomain)
		return json.Unmarshal(data, u.RegistrableDomain)
	}
	return fmt.Errorf("openproposal: the value is in no branch of Measurer")
}

// MarshalJSON encodes the branch the union holds.
func (u Measurer) MarshalJSON() ([]byte, error) {
	switch {
	case u.Side != nil:
		return json.Marshal(u.Side)
	case u.RegistrableDomain != nil:
		return json.Marshal(u.RegistrableDomain)
	}
	return nil, fmt.Errorf("openproposal: the Measurer holds no branch")
}

